 using System.ComponentModel.DataAnnotations;
namespace RaceDayNova.Mvc.Models;

public class UserDto { public int UserId { get; set; } public string FirstName { get; set; } = ""; public string LastName { get; set; } = ""; public string Email { get; set; } = ""; public string? Mobile { get; set; } public string UserRole { get; set; } = "Participant"; public DateTime CreatedOn { get; set; } public string? ProfileImageUrl { get; set; } }
public class LoginViewModel { [Required, EmailAddress] public string Email { get; set; } = ""; [Required, DataType(DataType.Password)] public string Password { get; set; } = ""; }
public class RegisterViewModel { [Required, StringLength(60)] public string FirstName { get; set; } = ""; [Required, StringLength(60)] public string LastName { get; set; } = ""; [Required, EmailAddress] public string Email { get; set; } = ""; [Required, MinLength(8), DataType(DataType.Password)] public string Password { get; set; } = ""; [Compare(nameof(Password)), DataType(DataType.Password), Display(Name="Confirm password")] public string ConfirmPassword { get; set; } = ""; [Phone] public string? Mobile { get; set; } public string Role { get; set; } = "Participant"; }
public class EventDto { public int EventId { get; set; } public int OrganiserId { get; set; } public string OrganiserName { get; set; } = ""; public string EventName { get; set; } = ""; public string EventType { get; set; } = "Running"; public DateOnly EventDate { get; set; } public TimeOnly StartTime { get; set; } public string Venue { get; set; } = ""; public string City { get; set; } = ""; public string Province { get; set; } = ""; public decimal DistanceKm { get; set; } public string? Description { get; set; } public string? RouteReference { get; set; } public string EventStatus { get; set; } = "Upcoming"; public DateTime CreatedOn { get; set; } public string? BannerImageUrl { get; set; } public List<EventCategoryDto> Categories { get; set; } = new(); }
public class EventCategoryDto { public int EventCategoryId { get; set; } public int EventId { get; set; } public int CategoryId { get; set; } public string CategoryName { get; set; } = ""; public short? AgeFrom { get; set; } public short? AgeTo { get; set; } public string? CategoryNote { get; set; } public decimal EntryFee { get; set; } public int? PlacesAvailable { get; set; } public int EnrolmentCount { get; set; } }
public class EventFormModel { public int EventId { get; set; } [Required, StringLength(160), Display(Name="Event name")] public string EventName { get; set; } = ""; [Required] public string EventType { get; set; } = "Running"; [Required, DataType(DataType.Date)] public DateOnly? EventDate { get; set; } [Required, DataType(DataType.Time)] public TimeOnly? StartTime { get; set; } [Required] public string Venue { get; set; } = ""; [Required] public string City { get; set; } = ""; [Required] public string Province { get; set; } = ""; [Range(0.01,100000)] public decimal DistanceKm { get; set; } [StringLength(800)] public string? Description { get; set; } public string? RouteReference { get; set; } public string? EventStatus { get; set; } public string? BannerImageUrl { get; set; } public IFormFile? BannerImage { get; set; } }
public class CategoryDto { public int CategoryId { get; set; } public string CategoryName { get; set; } = ""; public short? AgeFrom { get; set; } public short? AgeTo { get; set; } public string? CategoryNote { get; set; } }
public class CategoryFormModel { public int CategoryId { get; set; } [Required] public string CategoryName { get; set; } = ""; public short? AgeFrom { get; set; } public short? AgeTo { get; set; } public string? CategoryNote { get; set; } }
public class EnrolmentDto { public int EnrolmentId { get; set; } public int ParticipantId { get; set; } public string ParticipantName { get; set; } = ""; public string ParticipantEmail { get; set; } = ""; public int EventId { get; set; } public string EventName { get; set; } = ""; public DateOnly EventDate { get; set; } public int EventCategoryId { get; set; } public int CategoryId { get; set; } public string CategoryName { get; set; } = ""; public decimal EntryFee { get; set; } public DateTime EnrolledOn { get; set; } public string EnrolmentStatus { get; set; } = "Pending"; public bool HasResult { get; set; } }
public class ResultDto { public int ResultId { get; set; } public int EnrolmentId { get; set; } public int ParticipantId { get; set; } public string ParticipantName { get; set; } = ""; public int EventId { get; set; } public string EventName { get; set; } = ""; public DateOnly EventDate { get; set; } public string CategoryName { get; set; } = ""; public int? PositionNo { get; set; } public TimeSpan? FinishTime { get; set; } public int? PaceSecondsKm { get; set; } public string ResultStatus { get; set; } = "Finished"; public DateTime RecordedOn { get; set; } }
public class ProfileFormModel { [Required] public string FirstName { get; set; } = ""; [Required] public string LastName { get; set; } = ""; [Required, EmailAddress] public string Email { get; set; } = ""; [Phone] public string? Mobile { get; set; } public string? CurrentPassword { get; set; } public string? NewPassword { get; set; } public IFormFile? ProfilePicture { get; set; } }
public class ApiMessage { public string Message { get; set; } = ""; }

/// <summary>Weather snapshot returned by the API for an event.</summary>
public class WeatherViewModel { public int EventId { get; set; } public decimal? TemperatureC { get; set; } public decimal? WindKph { get; set; } public decimal? RainChance { get; set; } public string? Summary { get; set; } public string? ProviderName { get; set; } public bool IsCached { get; set; } }
